pre.code:
// 插入一条文档
db.users.insertOne({
    name: "张三",
    age: 25,
    city: "北京",
    tags: ["开发", "后端"]    // 数组类型，MySQL 做不到
})

// 插入多条
db.users.insertMany([
    { name: "李四", age: 30, city: "上海" },
    { name: "王五", age: 28, city: "广州" }
])

// 查所有文档
db.users.find()

// 条件查询（等价于 WHERE）
db.users.find({ city: "北京" })

// 多条件 AND
db.users.find({ city: "北京", age: 25 })

// 只返回指定字段（projection）
db.users.find({ city: "北京" }, { name: 1, age: 1, _id: 0 })
// 1 = 包含，0 = 排除

// 年龄大于 25
db.users.find({ age: { $gt: 25 } })

// 城市是北京或上海（OR）
db.users.find({ city: { $in: ["北京", "上海"] } })

// 年龄 20~30 之间（AND 隐式）
db.users.find({ age: { $gte: 20, $lte: 30 } })

// name 存在且以"张"开头
db.users.find({ name: { $exists: true, $regex: /^张/ } })

// 显式 OR
db.users.find({ $or: [
    { city: "北京" },
    { age: { $lt: 20 } }
]})

// 更新单条（$set 只改指定字段，其他不动）
db.users.updateOne(
    { name: "张三" },           // 过滤条件
    { $set: { age: 26 } }      // 更新内容
)

// 更新多条
db.users.updateMany(
    { city: "北京" },
    { $set: { status: "active" } }
)

// 常用更新操作符
db.users.updateOne(
    { name: "张三" },
    {
        $set: { city: "深圳" },        // 设置字段值
        $inc: { loginCount: 1 },       // 数值加 1
        $push: { tags: "新标签" },     // 往数组追加元素
        $unset: { tempField: "" }      // 删除字段
    }
)

// 删除单条
db.users.deleteOne({ name: "张三" })

// 删除多条
db.users.deleteMany({ city: "北京" })

// 清空集合（不删集合本身）
db.users.deleteMany({})

db.users.aggregate([
    // 阶段 1：过滤，只要 status 为 active 的
    { $match: { status: "active" } },

    // 阶段 2：按城市分组，统计数量
    { $group: {
        _id: "$city",           // 按 city 字段分组（$ 表示引用字段值）
        count: { $sum: 1 },     // 每匹配一条就 +1
        avgAge: { $avg: "$age" } // 顺便算平均年龄
    }},

    // 阶段 3：按 count 降序排列
    { $sort: { count: -1 } },   // -1 = 降序，1 = 升序

    // 阶段 4：只取前 5 条
    { $limit: 5 }
])

// 等价 SQL：
// SELECT t.*, u.name FROM task_records t
// LEFT JOIN users u ON t.user_id = u._id

db.task_records.aggregate([
    { $lookup: {
        from: "users",          // 要关联的集合
        localField: "user_id",  // 当前集合的字段
        foreignField: "_id",    // 关联集合的字段
        as: "user_info"         // 结果存到这个字段（数组）
    }},
    { $unwind: "$user_info" }   // 把数组展开成单条（可选）
])

// 原始文档：{ name: "张三", tags: ["开发", "后端", "Go"] }

db.users.aggregate([
    { $unwind: "$tags" }
])

// 展开后变成 3 条：
// { name: "张三", tags: "开发" }
// { name: "张三", tags: "后端" }
// { name: "张三", tags: "Go" }

// 创建单字段索引（1 = 升序，-1 = 降序）
db.users.createIndex({ city: 1 })

// 创建复合索引
db.users.createIndex({ city: 1, age: -1 })

// 创建唯一索引
db.users.createIndex({ email: 1 }, { unique: true })

// 查看集合所有索引
db.users.getIndexes()

// 删除索引
db.users.dropIndex("city_1")

// 查看查询是否走索引（类似 EXPLAIN）
db.users.find({ city: "北京" }).explain("executionStats")

// 查看当前数据库
db

// 查看所有集合
show collections

// 查看集合文档数量
db.users.countDocuments()

// 查看集合存储信息
db.users.stats()

// 查看集合索引大小
db.users.totalIndexSize()

// 查看当前正在执行的操作
db.currentOp()

// 杀掉某个操作
db.killOp(opId)

// 查看慢查询（类似 slow_query_log）
db.profile.find({ millis: { $gt: 100 } }).sort({ ts: -1 }).limit(10)

// 开启 profiling（记录所有操作）
db.setProfilingLevel(1, { slowms: 100 })  // 1 = 记录慢查询
db.setProfilingLevel(2)                     // 2 = 记录所有操作
db.setProfilingLevel(0)                     // 0 = 关闭
